fs.writeFileSync(path.join(root,'dist/app.js'),`const products=${JSON.stringify(products)};
document.getElementById('year').textContent=new Date().getFullYear();
const dialog=document.getElementById('product-dialog');
let lastTrigger=null;
document.querySelectorAll('[data-product]').forEach(button=>button.addEventListener('click',()=>{
 const product=products.find(item=>item.id===button.dataset.product);
 if(!product)return;
 lastTrigger=button;
 const src='assets/produse/dracula-design-'+product.file+'.jpeg';
 document.getElementById('dialog-image').src=src;
 document.getElementById('dialog-image').alt=product.name+' — imagine originală completă';
 document.getElementById('dialog-title').textContent=product.name;
 document.getElementById('dialog-category').textContent=product.category;
 document.getElementById('dialog-description').textContent=product.description;
 document.getElementById('dialog-detail').textContent=product.detail;
 document.getElementById('dialog-original').href=src;
 dialog.showModal();document.body.classList.add('modal-open');
}));
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastTrigger?.focus();});
`);
fs.writeFileSync(path.join(root,'README.md'),`# Dracula Design Office — site local

Previzualizare: http://127.0.0.1:4173

Deschide Porneste-site.cmd pentru repornire. Fișierul dist/index.html funcționează și direct în browser. Serverul ascultă doar pe acest calculator; site-ul nu este publicat online.

## Imagini organizate

Sursa: S:\\dracula-design. Cele 9 fișiere au fost organizate și redenumite în 01-brand, 02-produse, 03-colectii, 04-atmosfera și 99-duplicate. Duplicatul colecției business a fost păstrat separat. Fișierele originale nu au fost modificate; hash-urile SHA256 au fost verificate după mutare. inventar-imagini.csv păstrează corespondența dintre numele inițiale și cele noi.

Site-ul folosește 8 imagini originale distincte, copiate în dist/assets: logo-ul auriu, cinci planșe de produs, colecția business și fotografia de atmosferă. Nu au fost generate imagini sau logo-uri noi. Fotografiile sunt încadrate prin CSS; prezentarea completă a fiecărui produs poate fi deschisă prin clic.

## Cele cinci produse

Rucsac Business, Servietă Business, Portofel Signature, Geantă Tote, Eșarfă Signature. Textele sunt propuneri editoriale bazate pe fotografii. Nu sunt introduse prețuri, dimensiuni sau date de contact neconfirmate.

## Structură

- dist/index.html: pagina de prezentare.
- dist/styles.css: aspect pentru desktop și mobil.
- dist/app.js: detaliile produselor, dialog cu închidere prin buton sau Escape.
- dist/assets: imaginile și logo-ul existente.
- server.cjs: server local fără dependențe externe.

Paletă: negru #090909, roșu #a71e2e, auriu #b89a64. Tipografie serif, fotografii editoriale și accente discrete.
`);
console.log('Updated local site with original logo and five products.');
